/* Vaporwave — purple/pink/cyan gradients, chrome text, 80s grid horizon */
.theme-vaporwave {
  --bg: oklch(0.2 0.13 300);
  --surface: oklch(0.28 0.14 305 / 75%);
  --surface-2: oklch(0.34 0.15 310 / 80%);
  --fg: oklch(0.97 0.03 320);
  --fg-muted: oklch(0.82 0.08 320);
  --accent: oklch(0.75 0.22 340);
  --accent-fg: oklch(0.17 0.1 300);
  --accent-2: oklch(0.83 0.16 195);
  --line: oklch(0.83 0.16 195 / 45%);
  --success: oklch(0.8 0.17 165);
  --warning: oklch(0.86 0.16 90);
  --danger: oklch(0.7 0.23 15);

  --radius: 0.25rem;
  --radius-sm: 0.125rem;
  --radius-lg: 0.5rem;
  --radius-pill: 9999px;

  --shadow-1: 0 0 0 1px var(--line);
  --shadow-2: 0 0 24px -4px oklch(0.75 0.22 340 / 70%);
  --shadow-3: 0 0 48px -8px oklch(0.83 0.16 195 / 70%);
  --glow: 0 0 22px -2px oklch(0.75 0.22 340 / 80%);

  --border-width: 2px;
  --blur-amount: 8px;

  --font-display: "Orbitron", "Space Grotesk", sans-serif;
  --font-body: "Space Grotesk", "Inter", sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;

  --tracking-display: 0.06em;
  --label-transform: uppercase;
  --label-tracking: 0.22em;

  background-color: var(--bg);
  background-image:
    linear-gradient(oklch(0.83 0.16 195 / 35%) 1px, transparent 1px),
    linear-gradient(90deg, oklch(0.83 0.16 195 / 35%) 1px, transparent 1px),
    radial-gradient(50rem 30rem at 50% 100%, oklch(0.75 0.22 340 / 55%), transparent 70%),
    linear-gradient(180deg, oklch(0.18 0.12 295), oklch(0.3 0.16 320));
  background-size: 4rem 4rem, 4rem 4rem, 100% 100%, 100% 100%;
  background-position: bottom, bottom, center, center;
  background-attachment: fixed;
  color: var(--fg);
  font-family: var(--font-body);
}

.theme-vaporwave h1,
.theme-vaporwave h2 {
  font-family: var(--font-display);
  letter-spacing: var(--tracking-display);
  background-image: linear-gradient(
    180deg,
    oklch(0.99 0.02 320) 0%,
    oklch(0.86 0.1 320) 42%,
    oklch(0.62 0.18 330) 52%,
    oklch(0.95 0.06 200) 100%
  );
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  text-shadow: 0 0 24px oklch(0.75 0.22 340 / 45%);
}

.theme-vaporwave h3 {
  font-family: var(--font-display);
  letter-spacing: var(--tracking-display);
}

/* signature */
.theme-vaporwave { background-image: linear-gradient(oklch(0.2 0.12 310 / 60%), transparent 40%), repeating-linear-gradient(90deg, oklch(0.7 0.18 200 / 8%) 0 1px, transparent 1px 60px), repeating-linear-gradient(0deg, oklch(0.7 0.2 340 / 8%) 0 1px, transparent 1px 60px); }
.theme-vaporwave h1 { background: linear-gradient(180deg, oklch(0.85 0.15 200), oklch(0.7 0.25 340)); -webkit-background-clip: text; background-clip: text; color: transparent; text-transform: uppercase; }
.theme-vaporwave button { text-shadow: 0 0 8px color-mix(in oklab, var(--accent) 70%, transparent); }

/* depth */
.theme-vaporwave thead th { color: var(--accent-2); text-transform: uppercase; letter-spacing: 0.18em; font-family: var(--font-display); font-weight: 400; border-bottom: 2px solid var(--accent-2); background: oklch(0.24 0.13 305 / 60%); }
.theme-vaporwave td { border-bottom: 1px solid oklch(0.83 0.16 195 / 22%); }
.theme-vaporwave tbody tr:hover td { background: oklch(0.75 0.22 340 / 12%); text-shadow: 0 0 12px oklch(0.75 0.22 340 / 50%); }
.theme-vaporwave input, .theme-vaporwave textarea, .theme-vaporwave select { background: oklch(0.24 0.13 300 / 70%); border: 1px solid var(--line); color: var(--fg); }
.theme-vaporwave input:focus-visible, .theme-vaporwave textarea:focus-visible { outline: none; border-color: var(--accent); box-shadow: 0 0 18px -2px oklch(0.75 0.22 340 / 80%), inset 0 0 10px oklch(0.75 0.22 340 / 20%); }
.theme-vaporwave kbd { font-family: var(--font-mono); border: 1px solid var(--accent-2); background: linear-gradient(180deg, oklch(0.4 0.14 310), oklch(0.26 0.13 300)); color: var(--accent-2); padding: 0.1em 0.45em; text-shadow: 0 0 6px oklch(0.83 0.16 195 / 80%); }
.theme-vaporwave a { color: var(--accent-2); text-decoration: none; border-bottom: 1px solid oklch(0.83 0.16 195 / 50%); }
.theme-vaporwave a:hover { color: var(--accent); border-bottom-color: var(--accent); text-shadow: 0 0 14px oklch(0.75 0.22 340 / 80%); }
.theme-vaporwave ::selection { background: oklch(0.75 0.22 340); color: oklch(0.15 0.1 300); }
.theme-vaporwave ::-webkit-scrollbar { width: 12px; }
.theme-vaporwave ::-webkit-scrollbar-track { background: oklch(0.17 0.11 300); }
.theme-vaporwave ::-webkit-scrollbar-thumb { background: linear-gradient(180deg, var(--accent), var(--accent-2)); border-radius: 999px; box-shadow: 0 0 10px oklch(0.75 0.22 340 / 70%); }
.theme-vaporwave .label-caps { color: var(--accent-2); text-shadow: 0 0 10px oklch(0.83 0.16 195 / 70%); }
.theme-vaporwave .themed-border { border: 1px solid var(--accent-2); box-shadow: 0 0 20px -6px oklch(0.83 0.16 195 / 70%), inset 0 0 20px -10px oklch(0.75 0.22 340 / 50%); }
.theme-vaporwave hr { border: none; height: 2px; background: linear-gradient(90deg, transparent, var(--accent), var(--accent-2), transparent); box-shadow: 0 0 12px oklch(0.75 0.22 340 / 70%); }

/* alt mode: miami daylight — sun-bleached pastel, grid still on the horizon */
.theme-vaporwave.alt-mode {
  --bg: oklch(0.96 0.03 320);
  --surface: oklch(0.99 0.015 320 / 85%);
  --surface-2: oklch(0.93 0.05 200 / 85%);
  --fg: oklch(0.28 0.09 300);
  --fg-muted: oklch(0.48 0.08 310);
  --accent: oklch(0.62 0.24 345);
  --accent-fg: oklch(0.99 0.01 320);
  --accent-2: oklch(0.55 0.13 210);
  --line: oklch(0.55 0.13 210 / 40%);
  --shadow-1: 0 0 0 1px var(--line);
  --shadow-2: 0 8px 24px -8px oklch(0.62 0.24 345 / 35%);
  --shadow-3: 0 16px 44px -12px oklch(0.55 0.13 210 / 40%);
  background-image:
    linear-gradient(oklch(0.55 0.13 210 / 15%) 1px, transparent 1px),
    linear-gradient(90deg, oklch(0.55 0.13 210 / 15%) 1px, transparent 1px),
    radial-gradient(50rem 30rem at 50% 100%, oklch(0.85 0.11 340 / 55%), transparent 70%),
    linear-gradient(180deg, oklch(0.93 0.05 200), oklch(0.96 0.04 330));
  background-size: 4rem 4rem, 4rem 4rem, 100% 100%, 100% 100%;
  background-position: bottom, bottom, center, center;
  background-attachment: fixed;
}
.theme-vaporwave.alt-mode h1, .theme-vaporwave.alt-mode h2 { background-image: linear-gradient(180deg, oklch(0.45 0.16 300), oklch(0.62 0.24 345)); text-shadow: none; }
.theme-vaporwave.alt-mode thead th { background: oklch(0.93 0.05 200 / 70%); color: var(--accent-2); }
.theme-vaporwave.alt-mode input, .theme-vaporwave.alt-mode textarea, .theme-vaporwave.alt-mode select { background: oklch(0.99 0.01 320 / 80%); color: var(--fg); }
.theme-vaporwave.alt-mode kbd { background: linear-gradient(180deg, oklch(0.98 0.01 320), oklch(0.9 0.04 320)); color: var(--accent-2); text-shadow: none; }
.theme-vaporwave.alt-mode ::selection { background: var(--accent); color: var(--accent-fg); }
.theme-vaporwave.alt-mode ::-webkit-scrollbar-track { background: oklch(0.93 0.03 320); }

/* Bridge shadcn semantic variables to the theme tokens so stock shadcn/ui
   components are skinned by the theme. Scope-safe: applies inside the theme
   class only. */
[class*="theme-"] {
  --background: var(--bg);
  --foreground: var(--fg);
  --card: var(--surface);
  --card-foreground: var(--fg);
  --popover: var(--surface);
  --popover-foreground: var(--fg);
  --primary: var(--accent);
  --primary-foreground: var(--accent-fg);
  --secondary: var(--surface-2);
  --secondary-foreground: var(--fg);
  --muted: var(--surface-2);
  --muted-foreground: var(--fg-muted);
  --accent-foreground: var(--accent-fg);
  --border: var(--line);
  --input: var(--line);
  --ring: var(--accent);
  --destructive: var(--danger);
  --destructive-foreground: var(--accent-fg);

  /* Full app surface: sidebar, charts, app-level font + shadow + tracking vars.
     These are what real products (shadcn full kit, RootCX-style UI kits) consume —
     without them a retrofit looks half-themed. */
  --sidebar: var(--surface-2);
  --sidebar-foreground: var(--fg);
  --sidebar-primary: var(--accent);
  --sidebar-primary-foreground: var(--accent-fg);
  --sidebar-accent: color-mix(in oklab, var(--accent) 12%, var(--surface-2));
  --sidebar-accent-foreground: var(--fg);
  --sidebar-border: var(--line);
  --sidebar-ring: var(--accent);

  --chart-1: var(--accent);
  --chart-2: var(--accent-2);
  --chart-3: var(--success);
  --chart-4: var(--warning);
  --chart-5: var(--danger);

  --font-sans: var(--font-body);
  --font-heading: var(--font-app, var(--font-display));
  --font-serif: var(--font-display);

  --shadow-2xs: var(--shadow-1);
  --shadow-xs: var(--shadow-1);
  --shadow-sm: var(--shadow-1);
  --shadow: var(--shadow-2);
  --shadow-md: var(--shadow-2);
  --shadow-lg: var(--shadow-3);
  --shadow-xl: var(--shadow-3);
  --shadow-2xl: var(--shadow-3);

  --tracking-normal: 0em;
}

/* Base experience: make the theme own the canvas and native elements even in
   apps that never adopted semantic classes. Scoped to the theme wrapper. */
[class*="theme-"] {
  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}
[class*="theme-"] :is(h1, h2, h3, h4) { font-family: var(--font-display); }
[class*="theme-"] :is(code, pre, kbd, samp) { font-family: var(--font-mono); }
[class*="theme-"] ::selection { background: color-mix(in oklab, var(--accent) 30%, transparent); }

/* OPT-IN HARD MODE — add "sf-enforce" beside the theme class when the host app
   bakes font/shadow/radius literals into its compiled utilities (a var bridge
   cannot beat a literal). Targeted !important, fonts and surfaces only. */
[class*="theme-"].sf-enforce { font-family: var(--font-body) !important; }
[class*="theme-"].sf-enforce :is(h1, h2, h3, h4, [class*="font-heading"]) {
  font-family: var(--font-app, var(--font-display)) !important;
  letter-spacing: var(--tracking-display) !important;
}
/* Data stays data: metrics/KPIs keep the body face with aligned lining figures.
   The display face is for headlines ONLY — never on numbers. Opt specific
   elements INTO the display face with data-sf="display". */
[class*="theme-"] :is([class*="text-2xl"], [class*="text-3xl"], [class*="text-4xl"], [class*="text-5xl"]) {
  font-variant-numeric: lining-nums tabular-nums;
}
[class*="theme-"].sf-enforce [data-sf="display"] {
  font-family: var(--font-display) !important;
  letter-spacing: var(--tracking-display) !important;
}
[class*="theme-"] :is(.sf-num, [data-sf="num"]) {
  font-family: var(--font-body) !important;
  font-variant-numeric: lining-nums tabular-nums;
}
[class*="theme-"].sf-enforce :is(button, [role="button"]) { font-family: var(--font-ui, var(--font-body)) !important; }
[class*="theme-"].sf-enforce :is(code, pre, kbd) { font-family: var(--font-mono) !important; }
[class*="theme-"].sf-enforce :is(.bg-card, [class*="card"]) {
  box-shadow: var(--shadow-2) !important;
  border-radius: var(--radius-lg) !important;
  border: var(--border-width) solid var(--line) !important;
}
[class*="theme-"].sf-enforce :is([class*="shadow-sm"], [class*="shadow-md"]) { box-shadow: var(--shadow-1) !important; }
[class*="theme-"].sf-enforce :is([class*="shadow-lg"], [class*="shadow-xl"]) { box-shadow: var(--shadow-3) !important; }
